import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第24–31课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第24–31课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第16–23课","link":"/life/english/new-concept/book-1/review-part-03"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第32–38课","link":"/life/english/new-concept/book-1/review-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第16–23课","link":"/life/english/new-concept/book-1/review-part-03"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第32–38课","link":"/life/english/new-concept/book-1/review-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-04.md","filePath":"life/english/new-concept/book-1/review-part-04.md"}'),r={name:"life/english/new-concept/book-1/review-part-04.md"};function n(l,e,i,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第24–31课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第24–31课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第24–31课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第24–31课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-24-·-ones-与复数选择" tabindex="-1">Lesson 24 · ones 与复数选择 <a class="header-anchor" href="#lesson-24-·-ones-与复数选择" aria-label="Permalink to &quot;Lesson 24 · ones 与复数选择 {#lesson-24-·-ones-与复数选择}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I want the small ones beside the sink.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>补替代词：the small cups → the small ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> ones</p><p><strong>解析：</strong> 按本课规则判断：ones 替代已提到的复数可数名词；the clean ones 指前文的一组干净物品。some 后可接复数可数名词，也可接不可数名词；本课先用 some plates 这样的复数对象。give us/them 中代词是宾格。which glasses 的中心词为复数，回答时不要退回单数 one。</p></details><p><strong>表达迁移：</strong> 围绕“从多件物品中挑选一组”写两至三句，再读给同伴听。至少使用一次ones 与复数选择，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I want the small ones beside the sink. Please give us the clean plates.</p><p>I 是主语，want 是谓语，the small ones 是宾语；ones 指已知的复数物品，beside the sink 补充位置。 Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-024">回看本课</a></p><h2 id="lesson-25-·-there-is-与位置介词" tabindex="-1">Lesson 25 · there is 与位置介词 <a class="header-anchor" href="#lesson-25-·-there-is-与位置介词" aria-label="Permalink to &quot;Lesson 25 · there is 与位置介词 {#lesson-25-·-there-is-与位置介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There is a clock above the fridge.</p><h3 id="练习-1-24" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-24" aria-label="Permalink to &quot;练习 1 {#练习-1-24}&quot;">​</a></h3><p>填 be：There ___ a clock above the fridge.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：there is 用于引出某处存在的单数物品，后接 a/an + 单数名词；说某个已知物品在哪里则用 The ... is ...。in 表内部，on 表在表面，near 表附近。先区分“这里有一个什么”和“那个东西在哪里”，两种句型的信息起点不同。介词短语本身不能替代句子的谓语。</p></details><p><strong>表达迁移：</strong> 围绕“描述厨房物品的位置”写两至三句，再读给同伴听。至少使用一次there is 与位置介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There is a clock above the fridge. The kettle is on the shelf.</p><p>There is 引出新信息 a clock；above the fridge 说明时钟高于冰箱，不保证与冰箱表面接触。 The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-025">回看本课</a></p><h2 id="lesson-26-·-there-is-与位置介词" tabindex="-1">Lesson 26 · there is 与位置介词 <a class="header-anchor" href="#lesson-26-·-there-is-与位置介词" aria-label="Permalink to &quot;Lesson 26 · there is 与位置介词 {#lesson-26-·-there-is-与位置介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The kettle is on the shelf.</p><h3 id="练习-1-25" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-25" aria-label="Permalink to &quot;练习 1 {#练习-1-25}&quot;">​</a></h3><p>选择 on/in：水壶在架子表面，The kettle is ___ the shelf.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 按本课规则判断：there is 用于引出某处存在的单数物品，后接 a/an + 单数名词；说某个已知物品在哪里则用 The ... is ...。in 表内部，on 表在表面，near 表附近。先区分“这里有一个什么”和“那个东西在哪里”，两种句型的信息起点不同。介词短语本身不能替代句子的谓语。</p></details><p><strong>表达迁移：</strong> 围绕“描述厨房物品的位置”写两至三句，再读给同伴听。至少使用一次there is 与位置介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The kettle is on the shelf. There is a clock above the fridge.</p><p>The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。 There is 引出新信息 a clock；above the fridge 说明时钟高于冰箱，不保证与冰箱表面接触。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-026">回看本课</a></p><h2 id="lesson-27-·-there-are-与复数位置" tabindex="-1">Lesson 27 · there are 与复数位置 <a class="header-anchor" href="#lesson-27-·-there-are-与复数位置" aria-label="Permalink to &quot;Lesson 27 · there are 与复数位置 {#lesson-27-·-there-are-与复数位置}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There are two lamps beside the sofa.</p><h3 id="练习-1-26" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-26" aria-label="Permalink to &quot;练习 1 {#练习-1-26}&quot;">​</a></h3><p>填 be：There ___ two lamps.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：there are 后接复数名词，表示某处存在多件物品；问它们在哪里用 Where are they?。between ... and ... 表示在两个参照物之间，next to 表紧邻。there be 不能与 have 混成 There have。已知复数物品作主语时用 They are ...，其中 they 指物品，there 则是存在句的引导成分。</p></details><p><strong>表达迁移：</strong> 围绕“描述客厅多件家具的摆放”写两至三句，再读给同伴听。至少使用一次there are 与复数位置，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There are two lamps beside the sofa. The pictures are between the windows.</p><p>There are 引出复数物品 two lamps；beside the sofa 是地点短语。are 与 lamps 的复数相配合。 The pictures 是复数主语，所以用 are；between the windows 把多个窗户作为位置参照。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-027">回看本课</a></p><h2 id="lesson-28-·-there-are-与复数位置" tabindex="-1">Lesson 28 · there are 与复数位置 <a class="header-anchor" href="#lesson-28-·-there-are-与复数位置" aria-label="Permalink to &quot;Lesson 28 · there are 与复数位置 {#lesson-28-·-there-are-与复数位置}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The pictures are between the windows.</p><h3 id="练习-1-27" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-27" aria-label="Permalink to &quot;练习 1 {#练习-1-27}&quot;">​</a></h3><p>填 be：Where ___ the pictures?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：there are 后接复数名词，表示某处存在多件物品；问它们在哪里用 Where are they?。between ... and ... 表示在两个参照物之间，next to 表紧邻。there be 不能与 have 混成 There have。已知复数物品作主语时用 They are ...，其中 they 指物品，there 则是存在句的引导成分。</p></details><p><strong>表达迁移：</strong> 围绕“描述客厅多件家具的摆放”写两至三句，再读给同伴听。至少使用一次there are 与复数位置，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The pictures are between the windows. There are two lamps beside the sofa.</p><p>The pictures 是复数主语，所以用 are；between the windows 把多个窗户作为位置参照。 There are 引出复数物品 two lamps；beside the sofa 是地点短语。are 与 lamps 的复数相配合。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-028">回看本课</a></p><h2 id="lesson-29-·-祈使句与-must" tabindex="-1">Lesson 29 · 祈使句与 must <a class="header-anchor" href="#lesson-29-·-祈使句与-must" aria-label="Permalink to &quot;Lesson 29 · 祈使句与 must {#lesson-29-·-祈使句与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Please close the cupboard quietly.</p><h3 id="练习-1-28" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-28" aria-label="Permalink to &quot;练习 1 {#练习-1-28}&quot;">​</a></h3><p>补动词原形：Please ___ (close) the cupboard.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> close</p><p><strong>解析：</strong> 按本课规则判断：肯定祈使句通常以动词原形开头，省略主语 you；please 可放句首或句末，句末通常用逗号隔开。must 表示必要或要求，后接动词原形，不加 to。询问要做什么用 What must I do?，将 must 放在主语前。不要把命令与正在发生的动作混淆，Open ... 是要求，不是陈述。</p></details><p><strong>表达迁移：</strong> 围绕“理解整理房间的指令”写两至三句，再读给同伴听。至少使用一次祈使句与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please close the cupboard quietly. I must tidy my desk before lunch.</p><p>Please close 是礼貌指令，the cupboard 是 close 的宾语；quietly 是副词，修饰关柜子的动作。 I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-029">回看本课</a></p><h2 id="lesson-30-·-祈使句与-must" tabindex="-1">Lesson 30 · 祈使句与 must <a class="header-anchor" href="#lesson-30-·-祈使句与-must" aria-label="Permalink to &quot;Lesson 30 · 祈使句与 must {#lesson-30-·-祈使句与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I must tidy my desk before lunch.</p><h3 id="练习-1-29" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-29" aria-label="Permalink to &quot;练习 1 {#练习-1-29}&quot;">​</a></h3><p>删去错误词：I must to tidy my desk.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I must tidy my desk.</p><p><strong>解析：</strong> 按本课规则判断：肯定祈使句通常以动词原形开头，省略主语 you；please 可放句首或句末，句末通常用逗号隔开。must 表示必要或要求，后接动词原形，不加 to。询问要做什么用 What must I do?，将 must 放在主语前。不要把命令与正在发生的动作混淆，Open ... 是要求，不是陈述。</p></details><p><strong>表达迁移：</strong> 围绕“理解整理房间的指令”写两至三句，再读给同伴听。至少使用一次祈使句与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I must tidy my desk before lunch. Please close the cupboard quietly.</p><p>I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。 Please close 是礼貌指令，the cupboard 是 close 的宾语；quietly 是副词，修饰关柜子的动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-030">回看本课</a></p><h2 id="lesson-31-·-现在进行时单数" tabindex="-1">Lesson 31 · 现在进行时单数 <a class="header-anchor" href="#lesson-31-·-现在进行时单数" aria-label="Permalink to &quot;Lesson 31 · 现在进行时单数 {#lesson-31-·-现在进行时单数}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Nora is reading beside the window.</p><h3 id="练习-1-30" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-30" aria-label="Permalink to &quot;练习 1 {#练习-1-30}&quot;">​</a></h3><p>填 be：Nora ___ reading.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：现在进行时由 am/is/are + 动词 ing 构成，用于描述说话时或现阶段正在进行的动作。he/she/it 用 is，I 用 am。否定词 not 放在 be 后；问句将 be 提前。以不发音 e 结尾的动词通常去 e 加 ing，如 make → making，不能只写动词 ing 而漏掉 be。</p></details><p><strong>表达迁移：</strong> 围绕“描述此刻一个人正在做的事情”写两至三句，再读给同伴听。至少使用一次现在进行时单数，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Nora is reading beside the window. Is the cat sleeping under the chair?</p><p>Nora 为单数主语，is reading 构成现在进行时；beside the window 只提供地点，不参与谓语变化。 Is 从 is sleeping 中前置形成问句；the cat 是主语，under the chair 说明睡觉的位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-031">回看本课</a></p>',68)])])}const u=s(r,[["render",n]]);export{m as __pageData,u as default};
